solution.solution.cpp:
#include <cstdint>
#include <string>

constexpr std::uint64_t kUserLimit{ 0x00007FFFFFFF0000ull };

std::string probe(std::uint64_t address, std::uint64_t length, std::uint64_t alignment)
{
    if (length == 0) return "ok";
    if (address % alignment != 0) return "misaligned";
    const std::uint64_t last{ address + length - 1 };
    if (last < address || last >= kUserLimit) return "out of range";    // wrapped, or past user space
    return "ok";
}

unitTests:
TEST("an ordinary buffer") { CHECK_EQ(probe(0x1000, 16, 8), std::string("ok")); }
TEST("misaligned") { CHECK_EQ(probe(0x1004, 16, 8), std::string("misaligned")); CHECK_EQ(probe(0x1003, 2, 2), std::string("misaligned")); }
TEST("runs past the user limit") { CHECK_EQ(probe(0x00007FFFFFFEFFF0ull, 32, 1), std::string("out of range")); }
TEST("ends exactly at the limit") { CHECK_EQ(probe(0x00007FFFFFFEFFF0ull, 16, 1), std::string("ok")); }
TEST("a kernel address") { CHECK_EQ(probe(0xFFFFF80000000000ull, 8, 8), std::string("out of range")); }
TEST("wrapping round") { CHECK_EQ(probe(0x1000, 0xFFFFFFFFFFFFF000ull, 1), std::string("out of range")); }
TEST("zero length is accepted even for odd values") { CHECK_EQ(probe(0xFFFFFFFFFFFFFFFFull, 0, 8), std::string("ok")); }

